    {q:{ru:"Цена 200 грн снизилась на 10%. Сколько она стоит теперь?",ua:"Ціна 200 грн знизилась на 10%. Скільки вона коштує тепер?"},opts:["190 грн","180 грн","210 грн","220 грн"],correct:1}
