      f1:"sin(α ± β) = sin α·cos β ± cos α·sin β",
      f2:"cos(α ± β) = cos α·cos β ∓ sin α·sin β",
      f3:"tan(α ± β) = (tan α ± tan β) / (1 ∓ tan α·tan β)",
