      { q:{ru:"cot α равен:",ua:"cot α дорівнює:"}, opts:["1/sin α","cos α/sin α","1/cos α","sin α/cos α"], correct:1 },
      { q:{ru:"Область значений sec α:",ua:"Область значень sec α:"}, opts:["[−1;1]","ℝ","(−∞;−1]∪[1;+∞)","(0;+∞)"], correct:2 },
      { q:{ru:"csc²α − cot²α равно:",ua:"csc²α − cot²α дорівнює:"}, opts:["0","1","2","sin²α"], correct:1 },
      { q:{ru:"Период функции cot α равен:",ua:"Період функції cot α дорівнює:"}, opts:["π/2","π","2π","4π"], correct:1 }
