      a_yes:"aᶠ⁽ˣ⁾=aᵍ⁽ˣ⁾ ⟹ f(x)=g(x) — розв'яжи звичайне рівняння",
      a_q2:"Є структура a²ˣ, aˣ (можна замінити)?",
      a_yes2_label:"Так", a_no2_label:"Ні",
      a_subst:"Заміна t=aˣ (t>0) → квадратне рівняння → повернись до x=logₐt",
      a_factor:"Спробуй винести спільний множник за дужки",
      exTitle:"Приклади",
      ex1t:"Розв'яжіть: 2ˣ⁺¹ = 8",
      ex1s:"8 = 2³, отже 2ˣ⁺¹ = 2³ → x+1=3 → x=2",
      ex2t:"Розв'яжіть: 3²ˣ = 1/9",
      ex2s:"1/9 = 3⁻², отже 3²ˣ = 3⁻² → 2x=−2 → x=−1",
      ex3t:"Розв'яжіть: 4ˣ − 5·2ˣ + 4 = 0",
      ex3s:"4ˣ=(2ˣ)². Заміна t=2ˣ (t>0): t²−5t+4=0 → t₁=1, t₂=4. 2ˣ=1→x=0; 2ˣ=4→x=2",
      checkTitle:"Міні-перевірка"
