      ex3t:"Розв'яжіть: log₃(x−1) < log₃(5−x)",
      ex3s:"ОДЗ: x−1>0 і 5−x>0 → 1<x<5. Основа 3>1: x−1<5−x → 2x<6 → x<3. Підсумок: 1<x<3",
