      c2: "2. Додавання, віднімання, множення на число",
      c2p: "Додавати вектори можна двома способами. Вони завжди дають одну й ту саму відповідь, бо виходить та сама фігура.",
      a1: "<b>Правило трикутника:</b> a⃗ + b⃗ — вектор від початку a⃗ до кінця b⃗, якщо b⃗ прикласти «головою до хвоста» a⃗",
      a2: "<b>Правило паралелограма:</b> a⃗ + b⃗ — діагональ паралелограма, побудованого на a⃗ і b⃗",
