      a4: "<b>Множення на число:</b> k · a⃗ змінює довжину в |k| разів, а при k &lt; 0 ще й напрямок на протилежний",
      c2n: "У координатах усе зводиться до покоординатного рахунку — малюнок не потрібен:",
      c2f: "a⃗ = (a₁; a₂),  b⃗ = (b₁; b₂) &nbsp;→&nbsp; a⃗ + b⃗ = (a₁ + b₁;  a₂ + b₂) &nbsp;&nbsp;|&nbsp;&nbsp; a⃗ − b⃗ = (a₁ − b₁;  a₂ − b₂) &nbsp;&nbsp;|&nbsp;&nbsp; k · a⃗ = (k·a₁;  k·a₂)",
      c3: "3. Скалярний добуток",
      c3p: "Це єдина операція, яка змішує два вектори в одне число. У неї два рівносильні визначення — беріть те, що коротше у конкретній задачі.",
      s1: "<b>За координатами:</b> a⃗ · b⃗ = a₁·b₁ + a₂·b₂",
