      intro: "Векторы нужны не сами по себе, а как способ решать задачи. В этом уроке нет новых формул — только приёмы, которые превращают условие задачи в набор равенств. Хорошая новость: почти всегда достаточно двух инструментов — сложения координат и скалярного произведения.",
