      intro: "До сих пор стороны треугольника приходилось находить через координаты. Теперь есть два прямых пути. Если известны две стороны и угол между ними — работает теорема косинусов. Если известна сторона и два угла — теорема синусов. Обе формулы следуют из прямоугольного треугольника, и обе уже спрятаны в том, что вы проходили в прошлом уроке.",
      c1: "1. Теорема косинусов",
      c1p: "Обозначения стандартные: сторона a лежит напротив угла A, сторона b — напротив B, сторона c — напротив C.",
      k1: "<b>c² = a² + b² − 2·a·b·cos C</b> &nbsp;&nbsp; и циклически: a² = b² + c² − 2bc cos A, &nbsp;b² = a² + c² − 2ac cos B",
      k1n: "Эту формулу вы фактически уже знаете. Из прошлого урока: cos A = (b⃗ · c⃗)/(|b⃗|·|c⃗|). Подставьте это в формулу квадрата разности |b⃗ − c⃗|² = |b⃗|² + |c⃗|² − 2b⃗·c⃗ — и получите a² = b² + c² − 2bc cos A. Теорема косинусов это просто скалярное произведение, записанное буквами.",
      k1b: "<b>Форма с проекциями:</b> a = b·cos C + c·cos B. Она хороша как проверка: если ответ «поехал», значит проекции сложены не с тем знаком.",
      k1p: "Отдельно запомните вырожденный случай: при C = 90° имеем cos C = 0, и формула превращается в c² = a² + b². Это теорема Пифагора — частный случай теоремы косинусов, а не наоборот.",
