      c4: "4. Как выбрать нужную теорему",
      w1: "<b>Две стороны и угол между ними</b> → косинусов: найдите третью сторону.<br><b>Сторона и два угла</b> → синусов: найдите остальные стороны.<br><b>Три стороны</b> → сначала косинусов найдите угол, потом всё остальное.<br><b>Две стороны и угол не между ними</b> → синусов, но обязательно проверьте неоднозначность.",
