      n2: "<b>sin B &gt; 1</b> — такого треугольника не существует.<br><b>sin B = 1</b> — единственное решение, B = 90°.<br><b>0 &lt; sin B &lt; 1</b> — два решения: B и 180° − B. Оба треугольника подходят, если только оставшийся угол C остаётся положительным.",
      n3: "Правило отбора без вычислений: при A &lt; 90° второе решение существует тогда и только тогда, когда B₁ &gt; A. При A ≥ 90° решения всегда единственное — там сторона a обязана быть больше b.",
      n4: "Забыть про второе решение — самая частая ошибка на экзамене. Если sin дал вам arcsin, это ещё не весь ответ.",
