      o1: "<b>C = 90°</b> → c² = a² + b², то есть теорема Пифагора.<br><b>Прямоугольный треугольник</b> → R = c/2: описанная окружность имеет диаметр, равный гипотенузе.<br><b>Равносторонний треугольник</b> → a = 2R·sin 60°, откуда R = a/√3.",
