      ex4: "<b>4. Два решения.</b> a = 5, A = 30°, b = 7.<br>sin B = 7·0.5/5 = 0.7 → B ≈ 44.4° или 135.6°.<br>Отсюда C ≈ 105.6°, c ≈ 9.63 — <b>или</b> C ≈ 14.4°, c ≈ 2.49. Это два разных треугольника, и оба верны.",
