      o2: "<b>Остроугольный</b> треугольник: O внутри фигуры.<br><b>Прямоугольный</b>: O лежит на середине гипотенузы, и R = c/2 — это уже знакомое свойство окружности с диаметром.<br><b>Тупоугольный</b>: O снаружи, за пределами треугольника.",
