      c4: "4. Как решать задачи",
      w1: "<b>Нужен r</b> → найдите S и s, разделите.<br><b>Нужен R</b> → найдите S и все стороны, разделите a·b·c на 4S.<br><b>Прямоугольный треугольник</b> → обе формулы упрощаются: R = c/2, &nbsp;r = (a + b − c)/2. Площадь считать не нужно.<br><b>Неизвестна площадь</b> → пришлите к формуле Герона: S = √(s·(s − a)·(s − b)·(s − c)), и дальше всё по списку.",
      interLabel: "Конструктор — двигайте стороны и угол, переключайте режим",
