      ex2: "<b>2. Стороны 13, 14 и 15.</b><br>s = 21, &nbsp;S = √(21·8·7·6) = √7056 = <b>84</b>.<br>r = 84/21 = <b>4</b>, &nbsp;R = 13·14·15/(4·84) = 2730/336 = <b>65/8</b>",
      ex3: "<b>3. Равносторонний со стороной 12.</b><br>r = 12/(2√3) = <b>2√3</b>, &nbsp;R = 12/√3 = <b>4√3</b>.<br>Проверка на равенство Эйлера: R = 4√3 = 2·2√3 = 2r ✓",
      ex4: "<b>4. Даны радиусы.</b> R = 13, r = 5.<br>OI² = 13·(13 − 10) = 13·3 = <b>39</b>, откуда OI = √39.",
      ex5: "<b>5. Прямоугольный, без площади.</b> a = 9, b = 12, c = 15.<br>r = (a + b − c)/2 = (9 + 12 − 15)/2 = <b>3</b>, &nbsp;R = c/2 = <b>7.5</b>",
