      ex3: "<b>3. Пряма паралельна осі x і лежить на висоті 3. Знайти кут із площиною y = 0.</b><br>Пряма <b>паралельна</b> площині, отже φ = <b>0°</b>. Типова пастка: «висота 3» тут ні до чого, кут залежить лише від напрямку.",
