      <svg id="geoRe-bodies-svg" viewBox="0 0 400 240" role="img" aria-label="${A.bodies}" style="width:100%;height:auto;margin-top:8px;background:var(--paper);border:1px solid var(--line);border-radius:10px;"></svg>

