  l1:["senior"], l2:["senior"], l3:["senior"], l4:["senior"],
  l5:["senior"], l6:["senior"], l7:["senior"],
  /* модули 3–4 — показательная и логарифмическая, ступень 10–11 */
  e1:["senior"], e2:["senior"], e3:["senior"],
  lg3:["senior"], lg2:["senior"], lg4:["senior"], lg5:["senior"], gr1:["senior"],
  /* модуль 5 — планиметрия: базовые фигуры в 5–7, остальное в 8–9 */
  geo1:["middle","preSenior","senior"], geoTriangles:["middle","preSenior","senior"],
  geo2:["middle","preSenior","senior"], geoAreas:["middle","preSenior","senior"],
  geoPolygons:["preSenior","senior"], geo3:["preSenior","senior"], geoSimilarity:["preSenior","senior"],
  geoPythagor:["preSenior","senior"], geoCircles:["preSenior","senior"],
  geoVectors:["preSenior","senior"], geoVectorTasks:["preSenior","senior"],
  geoSineCos:["senior"],
  /* модуль 6 — начало стереометрии в 8–9, остальное в 10–11 */
  geoAxiom:["preSenior","senior"], geoPerp:["senior"], geoPrism:["senior"], geoRevolve:["senior"],
